export const getListCredentialsUrl = (params?: ListCredentialsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/credentials?${stringifiedParams}` : `/api/credentials`
}

/**
 * @summary List self-owned or strictly lower-ranked in-scope credentials
 */
